CREATE OR REPLACE FUNCTION private.can_edit_report(p_staff_id text, p_role_snapshot text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me text;
  myrole text;
  ownerrole text;
  admin_edit text;
begin
  me := private.current_staff_id();
  myrole := private.current_staff_role();

  if me is null then return false; end if;
  if myrole = 'KA_IPSRS' then return true; end if;
  if p_staff_id = me then return true; end if;
  if upper(coalesce(p_role_snapshot,'')) = 'KA_IPSRS' then return false; end if;

  select upper(coalesce(s.role,'')) into ownerrole
  from public.staff s
  where s.staff_id = p_staff_id
    and s.status = 'Aktif'
  limit 1;

  if ownerrole = 'KA_IPSRS' then return false; end if;

  if myrole = 'ADMINISTRASI' then
    select upper(value) into admin_edit
    from public.access_settings
    where key = 'ADMINISTRASI_EDIT';
    return coalesce(admin_edit,'NONAKTIF') = 'AKTIF';
  end if;

  return exists(
    select 1
    from public.edit_permissions ep
    where ep.granted_to_staff_id = me
      and ep.target_staff_id = p_staff_id
      and ep.is_active = true
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.can_view_report(p_staff_id text, p_role_snapshot text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me text;
  myrole text;
  ownerrole text;
  team_setting text;
begin
  me := private.current_staff_id();
  myrole := private.current_staff_role();

  if me is null then return false; end if;
  if myrole = 'KA_IPSRS' then return true; end if;
  if p_staff_id = me then return true; end if;
  if upper(coalesce(p_role_snapshot,'')) = 'KA_IPSRS' then return false; end if;

  select upper(coalesce(s.role,'')) into ownerrole
  from public.staff s
  where s.staff_id = p_staff_id
    and s.status = 'Aktif'
  limit 1;

  if ownerrole = 'KA_IPSRS' then return false; end if;

  select upper(value) into team_setting
  from public.access_settings
  where key = 'LAPORAN_TIM';

  return coalesce(team_setting,'AKTIF') = 'AKTIF';
end;
$function$

CREATE OR REPLACE FUNCTION private.prevent_report_owner_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.staff_id is distinct from old.staff_id then
    raise exception 'staff_id laporan tidak boleh diubah.';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_master_data_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at=now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_report_created_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.updated_at := now();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_master_data_parent()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.data_type in ('KATEGORI','AREA') and new.parent_id is not null then
    raise exception 'KATEGORI/AREA tidak boleh memiliki parent_id';
  end if;
  if new.data_type = 'ITEM' then
    if new.parent_id is null then raise exception 'ITEM wajib memiliki parent AREA'; end if;
    if not exists (select 1 from public.master_data p where p.id=new.parent_id and p.data_type='AREA') then
      raise exception 'Parent ITEM harus bertipe AREA';
    end if;
  end if;
  return new;
end;
$function$
